import React, { createContext, useContext, useEffect, useState } from 'react';
import {
  type User as FirebaseUser,
  onAuthStateChanged,
  signInWithEmailAndPassword,
  createUserWithEmailAndPassword,
  signOut,
  updateProfile,
  signInWithPopup,
  GoogleAuthProvider,
  GithubAuthProvider,
  deleteUser,
  sendEmailVerification,
  reload,
  sendPasswordResetEmail,
  verifyBeforeUpdateEmail,
  EmailAuthProvider,
  reauthenticateWithCredential
} from 'firebase/auth';
import {
  doc,
  setDoc,
  getDoc,
  updateDoc,
  deleteDoc,
  collection,
  query,
  where,
  getDocs,
  arrayRemove,
  onSnapshot
} from 'firebase/firestore';
import { auth, db } from '../firebase/config';
import type { User } from '../types';

interface AuthContextType {
  currentUser: User | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<void>;
  loginWithGoogle: () => Promise<void>;
  loginWithGithub: () => Promise<void>;
  signup: (email: string, password: string, displayName: string, username: string) => Promise<void>;
  logout: () => Promise<void>;
  deleteAccount: () => Promise<void>;
  sendEmailVerification: () => Promise<void>;
  resendEmailVerification: () => Promise<void>;
  checkEmailVerification: () => Promise<boolean>;
  sendPasswordReset: (email: string) => Promise<void>;
  updateUserEmail: (newEmail: string) => Promise<void>;
  refreshUserProfile: () => Promise<void>;
  reauthenticate: (password: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const createUserDocument = async (firebaseUser: FirebaseUser, displayName?: string, username?: string) => {
    const userRef = doc(db, 'users', firebaseUser.uid);
    const userSnap = await getDoc(userRef);

    // Determine the display name to use
    const finalDisplayName = displayName || firebaseUser.displayName || 'Anonymous';

    if (!userSnap.exists()) {
      const userData: any = {
        uid: firebaseUser.uid,
        email: firebaseUser.email!,
        displayName: finalDisplayName,
        createdAt: new Date(),
        username: username || '',
        usernameLower: username ? username.toLowerCase() : ''
      };

      // Only add photoURL if it exists (not undefined)
      if (firebaseUser.photoURL) {
        userData.photoURL = firebaseUser.photoURL;
      }

      await setDoc(userRef, userData);
      return userData as User;
    }

    // If document exists, check if we need to update displayName or username
    const existingData = userSnap.data() as User;
    const updates: any = {};
    let hasUpdates = false;

    if (finalDisplayName !== 'Anonymous' && existingData.displayName !== finalDisplayName) {
      updates.displayName = finalDisplayName;
      hasUpdates = true;
    }

    if (username && !existingData.username) {
      updates.username = username;
      updates.usernameLower = username.toLowerCase();
      hasUpdates = true;
    }

    // 3. Update device/country info on login
    const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
    const platform = isMobile ? 'mobile' : 'desktop';
    
    updates.lastLoginDevice = platform;
    updates.lastActive = new Date();
    hasUpdates = true;

    if (hasUpdates) {
      await updateDoc(userRef, updates);
      return { ...existingData, ...updates } as User;
    }

    return existingData;
  };

  const login = async (email: string, password: string) => {
    await signInWithEmailAndPassword(auth, email, password);
  };

  const loginWithGoogle = async () => {
    const provider = new GoogleAuthProvider();
    const result = await signInWithPopup(auth, provider);
    await createUserDocument(result.user);
  };

  const loginWithGithub = async () => {
    const provider = new GithubAuthProvider();
    const result = await signInWithPopup(auth, provider);
    await createUserDocument(result.user);
  };

  const signup = async (email: string, password: string, displayName: string, username: string) => {
    const { user } = await createUserWithEmailAndPassword(auth, email, password);
    await updateProfile(user, { displayName });
    const userData = await createUserDocument(user, displayName, username);
    // Send email verification
    await sendEmailVerification(user);
    // Manually update currentUser state to ensure displayName is immediately available
    setCurrentUser(userData);
  };

  const sendEmailVerificationLink = async () => {
    const user = auth.currentUser;
    if (!user) {
      throw new Error('No user is currently signed in');
    }
    if (user.emailVerified) {
      throw new Error('Email is already verified');
    }
    await sendEmailVerification(user);
  };

  const resendEmailVerificationLink = async () => {
    await sendEmailVerificationLink();
  };

  const checkEmailVerification = async (): Promise<boolean> => {
    const user = auth.currentUser;
    if (!user) {
      return false;
    }
    // Reload user to get latest emailVerified status
    await reload(user);
    return user.emailVerified;
  };

  const sendPasswordReset = async (email: string) => {
    await sendPasswordResetEmail(auth, email);
  };

  const updateUserEmail = async (newEmail: string) => {
    const user = auth.currentUser;
    if (!user) throw new Error('No user is currently signed in');

    try {
      // 1. Update in Firebase Auth (sends verification email to new address)
      await verifyBeforeUpdateEmail(user, newEmail);

      // 2. Update in Firestore
      const userRef = doc(db, 'users', user.uid);
      await updateDoc(userRef, {
        email: newEmail.toLowerCase()
      });

      // 3. Update local state
      if (currentUser) {
        setCurrentUser({ ...currentUser, email: newEmail });
      }
    } catch (error: any) {
      console.error('Error updating email:', error);
      throw error;
    }
  };

  const logout = async () => {
    await signOut(auth);
  };

  const deleteAccount = async () => {
    const user = auth.currentUser;
    if (!user) {
      throw new Error('No user is currently signed in');
    }

    const userId = user.uid;

    try {
      // 1. Delete user's containers (owned containers)
      const ownedContainersQuery = query(
        collection(db, 'vaults'),
        where('ownerId', '==', userId)
      );
      const ownedContainersSnapshot = await getDocs(ownedContainersQuery);
      const deleteContainerPromises = ownedContainersSnapshot.docs.map(docSnapshot =>
        deleteDoc(doc(db, 'vaults', docSnapshot.id))
      );
      await Promise.all(deleteContainerPromises);

      // 2. Remove user from shared containers (authorizedUsers array)
      const sharedContainersQuery = query(
        collection(db, 'vaults'),
        where('authorizedUsers', 'array-contains', userId)
      );
      const sharedContainersSnapshot = await getDocs(sharedContainersQuery);
      const updateContainerPromises = sharedContainersSnapshot.docs.map(docSnapshot =>
        updateDoc(doc(db, 'vaults', docSnapshot.id), {
          authorizedUsers: arrayRemove(userId)
        })
      );
      await Promise.all(updateContainerPromises);

      // 3. Delete user's notifications
      const notificationsQuery = query(
        collection(db, 'notifications'),
        where('userId', '==', userId)
      );
      const notificationsSnapshot = await getDocs(notificationsQuery);
      const deleteNotificationPromises = notificationsSnapshot.docs.map(docSnapshot =>
        deleteDoc(doc(db, 'notifications', docSnapshot.id))
      );
      await Promise.all(deleteNotificationPromises);

      // 4. Delete user's share invites (both sent and received)
      const sentInvitesQuery = query(
        collection(db, 'shareInvites'),
        where('invitedBy', '==', userId)
      );
      const sentInvitesSnapshot = await getDocs(sentInvitesQuery);
      const deleteSentInvitePromises = sentInvitesSnapshot.docs.map(docSnapshot =>
        deleteDoc(doc(db, 'shareInvites', docSnapshot.id))
      );

      // Also delete invites received by this user's email
      const userEmail = user.email?.toLowerCase();
      if (userEmail) {
        const receivedInvitesQuery = query(
          collection(db, 'shareInvites'),
          where('email', '==', userEmail)
        );
        const receivedInvitesSnapshot = await getDocs(receivedInvitesQuery);
        receivedInvitesSnapshot.docs.forEach(docSnapshot => {
          deleteSentInvitePromises.push(deleteDoc(doc(db, 'shareInvites', docSnapshot.id)));
        });
      }
      await Promise.all(deleteSentInvitePromises);

      // 5. Delete user's container permissions
      const permissionsQuery = query(
        collection(db, 'vaultPermissions'),
        where('userId', '==', userId)
      );
      const permissionsSnapshot = await getDocs(permissionsQuery);
      const deletePermissionPromises = permissionsSnapshot.docs.map(docSnapshot =>
        deleteDoc(doc(db, 'vaultPermissions', docSnapshot.id))
      );
      await Promise.all(deletePermissionPromises);

      // 6. Delete user's share links
      const shareLinksQuery = query(
        collection(db, 'shareLinks'),
        where('createdBy', '==', userId)
      );
      const shareLinksSnapshot = await getDocs(shareLinksQuery);
      const deleteShareLinkPromises = shareLinksSnapshot.docs.map(docSnapshot =>
        deleteDoc(doc(db, 'shareLinks', docSnapshot.id))
      );
      await Promise.all(deleteShareLinkPromises);

      // 7. Delete user document from Firestore
      const userRef = doc(db, 'users', userId);
      await deleteDoc(userRef);

      // 8. Delete user from Firebase Auth (this must be last)
      await deleteUser(user);
    } catch (error: any) {
      console.error('Error deleting account:', error);
      throw new Error(`Failed to delete account: ${error.message}`);
    }
  };

  useEffect(() => {
    let unsubscribeUser: (() => void) | undefined;

    const unsubscribeAuth = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        // Initial creation if document doesn't exist
        await createUserDocument(firebaseUser);
        
        // Setup real-time listener for current user data
        const userRef = doc(db, 'users', firebaseUser.uid);
        unsubscribeUser = onSnapshot(userRef, (userSnap: any) => {
          if (userSnap.exists()) {
            setCurrentUser(userSnap.data() as User);
          }
          setLoading(false);
        }, (error: any) => {
          console.error("User document sync error:", error);
          setLoading(false);
        });
      } else {
        if (unsubscribeUser) unsubscribeUser();
        setCurrentUser(null);
        setLoading(false);
      }
    });

    return () => {
      unsubscribeAuth();
      if (unsubscribeUser) unsubscribeUser();
    };
  }, []);

  const refreshUserProfile = async () => {
    const user = auth.currentUser;
    if (!user) return;
    const userRef = doc(db, 'users', user.uid);
    const userSnap = await getDoc(userRef);
    if (userSnap.exists()) {
      setCurrentUser(userSnap.data() as User);
    }
  };

  const value: AuthContextType = {
    currentUser,
    loading,
    login,
    loginWithGoogle,
    loginWithGithub,
    signup,
    logout,
    deleteAccount,
    sendEmailVerification: sendEmailVerificationLink,
    resendEmailVerification: resendEmailVerificationLink,
    checkEmailVerification,
    sendPasswordReset,
    updateUserEmail,
    refreshUserProfile,
    reauthenticate: async (password: string) => {
      const user = auth.currentUser;
      if (!user) throw new Error('No user is currently signed in');
      const credential = EmailAuthProvider.credential(user.email!, password);
      await reauthenticateWithCredential(user, credential);
    }
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
};
