import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { useContainer } from '../contexts/ContainerContext';
import { X, Link as LinkIcon, Sparkles, Tag, Plus, Loader2 } from 'lucide-react';
import LinkPreviewService from '../services/linkPreviewService';

interface AddLinkModalProps {
  isOpen: boolean;
  onClose: () => void;
  containerId: string;
  containerColor?: string;
}

import { useTranslation } from 'react-i18next';

const AddLinkModal: React.FC<AddLinkModalProps> = ({ isOpen, onClose, containerId, containerColor }) => {
  const { t } = useTranslation();

  const { addLinkToContainer, updateLinkInContainer, bulkAddLinksToContainer } = useContainer();
  const [activeTab, setActiveTab] = useState<'single' | 'bulk'>('single');
  const [bulkInput, setBulkInput] = useState('');
  const [stagedLinks, setStagedLinks] = useState<{ id: string, url: string, title: string, favicon: string | null }[]>([]);
  const [formData, setFormData] = useState<{
    title: string;
    url: string;
    description: string;
    githubData?: any;
    image?: string;
  }>({
    title: '',
    url: '',
    description: ''
  });
  const [loading, setLoading] = useState(false);
  const [isAutoFetching, setIsAutoFetching] = useState(false);
  const [isTitleAutoFilled, setIsTitleAutoFilled] = useState(false);
  const [isDescAutoFilled, setIsDescAutoFilled] = useState(false);
  const [error, setError] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [tagInput, setTagInput] = useState('');
  const [fetchTimeout, setFetchTimeout] = useState<any>(null);
  const [fetchSequence, setFetchSequence] = useState(0);

  useEffect(() => {
    if (isAutoFetching) {
      setFetchSequence(0);
      const interval = setInterval(() => {
        setFetchSequence(prev => (prev < 3 ? prev + 1 : prev));
      }, 500);
      return () => clearInterval(interval);
    } else {
      setFetchSequence(0);
    }
  }, [isAutoFetching]);

  // Helper to normalize URL
  const normalizeUrl = (url: string) => {
    const trimmed = url.trim();
    if (!trimmed) return '';

    // Check if it starts with http:// or https://
    if (!/^https?:\/\//i.test(trimmed)) {
      return `https://${trimmed}`;
    }
    return trimmed;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.title.trim() || !formData.url.trim()) {
      setError(t('container.modals.addLink.errors.required'));
      return;
    }

    const normalizedUrl = normalizeUrl(formData.url);

    // Basic URL validation with normalized URL
    try {
      new URL(normalizedUrl);
    } catch {
      setError(t('container.modals.addLink.errors.invalidUrl'));
      return;
    }

    try {
      setError('');
      setLoading(true);

      // 1. Add link immediately without waiting for favicon
      // This makes the UI feel much faster
      let finalTags = [...tags];
      if (tagInput.trim()) {
        const remainingTags = tagInput.split(',')
          .map(t => t.trim().toLowerCase())
          .filter(t => t !== "" && !finalTags.includes(t));
        finalTags.push(...remainingTags);
      }

      const linkId = await addLinkToContainer(containerId, {
        title: formData.title.trim(),
        url: normalizedUrl,
        description: formData.description.trim(),
        favicon: undefined, // Will be updated in background
        tags: finalTags,
        githubData: formData.githubData
      });

      // 2. Close modal and reset form immediately
      setFormData({ title: '', url: '', description: '' });
      setIsTitleAutoFilled(false);
      setIsDescAutoFilled(false);
      setLoading(false);
      onClose();

      // 3. Fetch full preview in background (Fire & Forget)
      LinkPreviewService.fetchLinkPreview(normalizedUrl)
        .then(preview => {
          const updates: any = {};
          if (preview.favicon) updates.favicon = preview.favicon;
          if (preview.githubData) updates.githubData = preview.githubData;

          if (Object.keys(updates).length > 0) {
            updateLinkInContainer(containerId, linkId, updates)
              .catch(err => console.error('Background update failed:', err));
          }
        })
        .catch(() => {
          // Silent failure is acceptable
        });

    } catch (err: any) {
      setError(err.message || t('container.modals.addLink.errors.failed'));
      setLoading(false);
    }
  };

  // Parse links from bulk input
  useEffect(() => {
    if (activeTab !== 'bulk') return;

    const regex = /(https?:\/\/[^\s]+)/g;
    const matches = bulkInput.match(regex);
    
    if (matches) {
      const newStaged = matches.map((url, i) => {
        let title = url;
        try {
          const u = new URL(url);
          title = u.hostname.replace(/^www\./, '');
        } catch(e) {}
        
        return {
          id: `staged_${Date.now()}_${i}`,
          url: url,
          title: title,
          favicon: LinkPreviewService.getFaviconUrl(url)
        };
      });
      // Remove duplicates by url
      const uniqueLinks = Array.from(new Map(newStaged.map(item => [item.url, item])).values());
      setStagedLinks(uniqueLinks);
    } else {
      setStagedLinks([]);
    }
  }, [bulkInput, activeTab]);

  const removeStagedLink = (idToRemove: string) => {
    setStagedLinks(prev => prev.filter(l => l.id !== idToRemove));
  };

  const handleBulkSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (stagedLinks.length === 0) return;
    
    try {
      setError('');
      setLoading(true);
      
      let finalTags = [...tags];
      if (tagInput.trim()) {
        const remainingTags = tagInput.split(',')
          .map(t => t.trim().toLowerCase())
          .filter(t => t !== "" && !finalTags.includes(t));
        finalTags.push(...remainingTags);
      }

      const linksData = stagedLinks.map(link => ({
        title: link.title,
        url: link.url,
        description: '',
        tags: finalTags,
        favicon: link.favicon || undefined
      }));

      await bulkAddLinksToContainer(containerId, linksData);

      setBulkInput('');
      setStagedLinks([]);
      setTags([]);
      setTagInput('');
      setLoading(false);
      onClose();

    } catch (err: any) {
      setError(err.message || t('container.modals.addLink.errors.failed'));
      setLoading(false);
    }
  };

  const handleUrlScan = (url: string) => {
    const trimmedUrl = url.trim();
    if (!trimmedUrl) {
      setIsAutoFetching(false);
      return;
    }

    const normalizedUrl = normalizeUrl(trimmedUrl);

    try {
      new URL(normalizedUrl);
    } catch {
      return;
    }

    if (fetchTimeout) clearTimeout(fetchTimeout);

    const timeout = setTimeout(async () => {
      try {
        setIsAutoFetching(true);
        const preview = await LinkPreviewService.fetchLinkPreview(normalizedUrl);

        setFormData(prev => {
          const newData = { ...prev };

          // Only fill if current value is empty or was previously auto-filled
          if ((!prev.title || isTitleAutoFilled) && preview.title) {
            newData.title = preview.title;
            setIsTitleAutoFilled(true);
          }

          if ((!prev.description || isDescAutoFilled) && preview.description) {
            newData.description = preview.description;
            setIsDescAutoFilled(true);
          }

          if (preview.githubData) {
            newData.githubData = preview.githubData;
          }

          return newData;
        });
      } catch (err) {
        console.warn('Scan failed:', err);
      } finally {
        setIsAutoFetching(false);
      }
    }, 1000);

    setFetchTimeout(timeout);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;

    if (name === 'title') setIsTitleAutoFilled(false);
    if (name === 'description') setIsDescAutoFilled(false);

    setFormData(prev => ({
      ...prev,
      [name]: value
    }));

    if (name === 'url') {
      handleUrlScan(value);
    }
  };

  const clearField = (field: 'title' | 'description' | 'url') => {
    if (field === 'url') {
      setFormData({ title: '', url: '', description: '' });
      setIsTitleAutoFilled(false);
      setIsDescAutoFilled(false);
      setIsAutoFetching(false);
      if (fetchTimeout) clearTimeout(fetchTimeout);
    } else {
      setFormData(prev => ({ ...prev, [field]: '' }));
      if (field === 'title') setIsTitleAutoFilled(false);
      if (field === 'description') setIsDescAutoFilled(false);
    }
  };

  const handleAddTag = (text?: string) => {
    const rawInput = text !== undefined ? text : tagInput;
    const individualTags = rawInput.split(',').map(tag => tag.trim().toLowerCase()).filter(tag => tag !== "");

    setTags(prevTags => {
      const newTags = [...prevTags];
      individualTags.forEach(tag => {
        if (!newTags.includes(tag)) {
          newTags.push(tag);
        }
      });
      return newTags;
    });
    setTagInput('');
  };

  const removeTag = (tagToRemove: string) => {
    setTags(tags.filter(t => t !== tagToRemove));
  };

  useEffect(() => {
    if (!isOpen) {
      setFormData({ title: '', url: '', description: '' });
      setBulkInput('');
      setStagedLinks([]);
      setActiveTab('single');
      setTags([]);
      setTagInput('');
      setIsTitleAutoFilled(false);
      setIsDescAutoFilled(false);
      setIsAutoFetching(false);
      setLoading(false);
      setError('');
      if (fetchTimeout) clearTimeout(fetchTimeout);
    }
  }, [isOpen]);

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) {
        onClose();
      }
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return createPortal(
    <div
      className="modal-overlay"
      onClick={onClose}
      style={{ '--primary': containerColor } as React.CSSProperties}
    >
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>{t('container.modals.addLink.title')}</h2>
          <button onClick={onClose} className="modal-close">
            <X className="h-6 w-6" />
          </button>
        </div>

        <div className="add-link-tabs" role="tablist" aria-label={t('container.modals.addLink.title')}>
          <button
            type="button"
            role="tab"
            aria-selected={activeTab === 'single'}
            className={`add-link-tab ${activeTab === 'single' ? 'active' : ''}`}
            onClick={() => setActiveTab('single')}
          >
            <LinkIcon size={16} />
            <span>{t('container.modals.addLink.tabs.single', 'Single Link')}</span>
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={activeTab === 'bulk'}
            className={`add-link-tab ${activeTab === 'bulk' ? 'active' : ''}`}
            onClick={() => setActiveTab('bulk')}
          >
            <Plus size={16} />
            <span>{t('container.modals.addLink.tabs.bulk', 'Bulk Add')}</span>
          </button>
        </div>

        {activeTab === 'single' ? (
          <>
            <form id="add-link-form" onSubmit={handleSubmit} className="modal-body">
              {error && (
                <div className="error-message">
                  {error}
                </div>
              )}

          <div className="form-group">
            <label htmlFor="url" className="form-label">
              {t('container.modals.addLink.url')} *
            </label>
            <div className={`url-input-wrapper ${formData.url ? 'input-with-clear' : ''}`}>
              <input
                id="url"
                name="url"
                type="text"
                required
                value={formData.url}
                onChange={handleChange}
                className={`form-input ${isAutoFetching ? 'border-primary' : ''}`}
                placeholder={t('container.modals.addLink.placeholders.url')}
                disabled={loading}
              />
              {formData.url && !loading && (
                <button type="button" onClick={() => clearField('url')} className="input-clear-btn" title={t('container.modals.addLink.tooltips.clearUrl')}>
                  <X size={12} />
                </button>
              )}
            </div>
            {isAutoFetching && (
              <div className="mt-2 p-3 rounded-lg flex flex-col gap-2" style={{ backgroundColor: 'rgba(var(--primary-rgb), 0.05)', border: '1px solid rgba(var(--primary-rgb), 0.1)' }}>
                <div className="flex justify-between items-center text-xs">
                  <span className="flex items-center gap-1.5 text-primary font-medium">
                    <Loader2 size={12} className="animate-spin" />
                    {t(`container.modals.addLink.fetching.step${fetchSequence + 1}`)}
                  </span>
                  <span className="text-gray-500 font-medium" style={{ opacity: 0.7 }}>
                    ~1s
                  </span>
                </div>
                <div className="h-1.5 w-full bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                  <div
                    className="h-full bg-primary transition-all duration-500 ease-out rounded-full"
                    style={{ width: `${(fetchSequence + 1) * 25}%` }}
                  />
                </div>
              </div>
            )}
          </div>

          <div className="form-group">
            <label htmlFor="title" className="form-label">
              {t('container.modals.addLink.linkTitle')} *
              {isTitleAutoFilled && (
                <span className="auto-filled-hint">
                  <Sparkles size={10} /> {t('container.modals.addLink.autoFilled')}
                </span>
              )}
              <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginLeft: '10px', float: 'right' }}>
                {formData.title.length}/100
              </span>
            </label>
            <div className={`input-with-icon ${isTitleAutoFilled ? 'input-with-magic' : ''} ${formData.title ? 'input-with-clear' : ''}`}>
              {isTitleAutoFilled && <Sparkles className="input-magic-icon" size={16} />}
              <input
                id="title"
                name="title"
                type="text"
                required
                value={formData.title}
                onChange={handleChange}
                className="form-input"
                placeholder={t('container.modals.addLink.placeholders.title')}
                disabled={loading}
              />
              {formData.title && !loading && (
                <button type="button" onClick={() => clearField('title')} className="input-clear-btn" title={t('container.modals.addLink.tooltips.clearTitle')}>
                  <X size={12} />
                </button>
              )}
            </div>
          </div>

          <div className="form-group">
            <label htmlFor="description" className="form-label">
              {t('container.modals.addLink.description')}
              {isDescAutoFilled && (
                <span className="auto-filled-hint">
                  <Sparkles size={10} /> {t('container.modals.addLink.autoFilled')}
                </span>
              )}
              <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginLeft: '10px', float: 'right' }}>
                {formData.description.length}/200
              </span>
            </label>
            <div className={`input-with-icon ${isDescAutoFilled ? 'input-with-magic' : ''} ${formData.description ? 'input-with-clear' : ''}`}>
              {isDescAutoFilled && <Sparkles className="input-magic-icon" size={16} />}
              <textarea
                id="description"
                name="description"
                value={formData.description}
                onChange={handleChange}
                className="form-input resize-none"
                rows={3}
                placeholder={t('container.modals.addLink.placeholders.description')}
                disabled={loading}
              />
              {formData.description && !loading && (
                <button type="button" onClick={() => clearField('description')} className="input-clear-btn" title={t('container.modals.addLink.tooltips.clearDescription')}>
                  <X size={12} />
                </button>
              )}
            </div>
          </div>

          <div className="form-group">
            <label htmlFor="tags" className="form-label">
              {t('container.modals.addLink.tags')}
            </label>
            <div className="tags-input-wrapper">
              <div className="tags-list">
                {tags.map(tag => (
                  <span key={tag} className="tag-badge">
                    {tag}
                    <button type="button" onClick={() => removeTag(tag)} className="remove-tag">
                      <X size={10} />
                    </button>
                  </span>
                ))}
              </div>
              <div className="tag-input-field-wrapper">
                <div className="tag-input-icon">
                  <Tag size={16} />
                </div>
                <input
                  type="text"
                  value={tagInput}
                  onChange={(e) => {
                    const value = e.target.value;
                    if (value.endsWith(',')) {
                      handleAddTag(value);
                    } else {
                      setTagInput(value);
                    }
                  }}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      e.preventDefault();
                      handleAddTag();
                    }
                  }}
                  className="form-input tag-input-padding"
                  placeholder={t('container.modals.addLink.placeholders.tags')}
                />
                <button
                  type="button"
                  onClick={() => handleAddTag()}
                  className="tag-add-btn"
                  title={t('container.modals.addLink.tooltips.addTag')}
                >
                  <Plus size={16} />
                </button>
              </div>
            </div>
          </div>
        </form>
        <div className="modal-footer">
          <button type="button" onClick={onClose} disabled={loading} className="btn-cancel">
            {t('container.modals.addLink.buttons.cancel')}
              </button>
              <button type="submit" form="add-link-form" disabled={loading} className="btn-primary flex items-center gap-2">
                {loading ? (
                  <><div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>{t('container.modals.addLink.buttons.adding')}</>
                ) : (
                  <><LinkIcon className="h-4 w-4" />{t('container.modals.addLink.buttons.add')}</>
                )}
              </button>
            </div>
          </>
        ) : (
          <>
            <form id="bulk-link-form" onSubmit={handleBulkSubmit} className="modal-body">
              {error && <div className="error-message">{error}</div>}
              
              <div className="form-group bulk-input-group">
                <label htmlFor="bulk-links" className="form-label">
                  {t('container.modals.addLink.bulkInputLabel')}
                </label>
                <textarea
                  id="bulk-links"
                  value={bulkInput}
                  onChange={(e) => setBulkInput(e.target.value)}
                  className="form-input bulk-links-input"
                  rows={6}
                  placeholder={t('container.modals.addLink.bulkInputPlaceholder', 'Paste your text or links here...')}
                  disabled={loading}
                />
              </div>

              {stagedLinks.length > 0 && (
                <div className="bulk-preview">
                  <div className="bulk-preview-header">
                    <h3>
                      {t('container.modals.addLink.foundLinks', '{{count}} links found').replace('{{count}}', stagedLinks.length.toString())}
                    </h3>
                    <span>{t('container.modals.addLink.bulkReady')}</span>
                  </div>
                  <div className="bulk-links-list">
                    {stagedLinks.map((link) => (
                      <div key={link.id} className="bulk-link-item">
                        {link.favicon ? (
                          <img src={link.favicon} alt="" className="bulk-link-favicon" onError={(e) => { (e.target as HTMLImageElement).style.display = 'none'; }} />
                        ) : (
                          <span className="bulk-link-favicon-fallback"><LinkIcon size={15} /></span>
                        )}
                        <div className="bulk-link-copy">
                          <p>{link.title}</p>
                          <span>{link.url}</span>
                        </div>
                        <button
                          type="button"
                          onClick={() => removeStagedLink(link.id)}
                          className="bulk-link-remove"
                          title={t('container.modals.addLink.removeLink')}
                        >
                          <X size={14} />
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              <div className="form-group bulk-tags-group">
                <label className="form-label">{t('container.modals.addLink.bulkTags', 'Tags for all links')}</label>
                <div className="tags-input-wrapper">
                  <div className="tags-list">
                    {tags.map(tag => (
                      <span key={tag} className="tag-badge">
                        {tag}
                        <button type="button" onClick={() => removeTag(tag)} className="remove-tag">
                          <X size={10} />
                        </button>
                      </span>
                    ))}
                  </div>
                  <div className="tag-input-field-wrapper">
                    <div className="tag-input-icon">
                      <Tag size={16} />
                    </div>
                    <input
                      type="text"
                      value={tagInput}
                      onChange={(e) => {
                        const value = e.target.value;
                        if (value.endsWith(',')) {
                          handleAddTag(value);
                        } else {
                          setTagInput(value);
                        }
                      }}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          handleAddTag();
                        }
                      }}
                      className="form-input tag-input-padding"
                      placeholder={t('container.modals.addLink.placeholders.tags')}
                    />
                    <button type="button" onClick={() => handleAddTag()} className="tag-add-btn" title={t('container.modals.addLink.tooltips.addTag')}>
                      <Plus size={16} />
                    </button>
                  </div>
                </div>
              </div>
            </form>
            <div className="modal-footer">
              <button type="button" onClick={onClose} disabled={loading} className="btn-cancel">
                {t('container.modals.addLink.buttons.cancel')}
              </button>
              <button type="submit" form="bulk-link-form" disabled={loading || stagedLinks.length === 0} className="btn-primary flex items-center gap-2">
                {loading ? (
                  <><div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div></>
                ) : (
                  <><Plus className="h-4 w-4" />{t('container.modals.addLink.bulkSubmit', 'Add {{count}} Links').replace('{{count}}', stagedLinks.length.toString())}</>
                )}
              </button>
            </div>
          </>
        )}
      </div>
    </div>,
    document.body
  );
};

export default AddLinkModal;
