import React from 'react';
import { NavLink } from 'react-router-dom';
import { Home, Tag, Settings, Plus } from 'lucide-react';
import { FiInbox } from "react-icons/fi";
import { useAuth } from '../contexts/AuthContext';
import { useLocation } from 'react-router-dom';
import { useTranslation } from 'react-i18next';

const BottomNavigation: React.FC = () => {
    const { currentUser } = useAuth();
    const location = useLocation();
    const { t } = useTranslation();

    if (!currentUser) return null;

    const handlePlusClick = () => {
        const isContainerDetails = location.pathname.startsWith('/c/');

        if (isContainerDetails) {
            if ((window as any).dispatchSetShowAddLinkModal) {
                (window as any).dispatchSetShowAddLinkModal(true);
            }
        } else {
            if ((window as any).dispatchSetShowCreateModal) {
                (window as any).dispatchSetShowCreateModal(true);
            }
        }
    };

    return (
        <nav className="bottom-nav">
            <NavLink to="/dashboard" className={({ isActive }) => `bottom-nav-item ${isActive ? 'active' : ''}`}>
                <Home size={24} />
                <span>{t('bottomNav.home')}</span>
            </NavLink>
            <NavLink to="/tags" className={({ isActive }) => `bottom-nav-item ${isActive ? 'active' : ''}`}>
                <Tag size={24} />
                <span>{t('bottomNav.tags')}</span>
            </NavLink>
            <div className="bottom-nav-item center-item" onClick={handlePlusClick}>
                <div className="center-item-inner">
                    <Plus size={32} />
                </div>
            </div>
            <NavLink to="/requests" className={({ isActive }) => `bottom-nav-item ${isActive ? 'active' : ''}`}>
                <FiInbox size={24} />
                <span>{t('bottomNav.invitations')}</span>
            </NavLink>
            <NavLink to="/settings" className={({ isActive }) => `bottom-nav-item ${isActive ? 'active' : ''}`}>
                <Settings size={24} />
                <span>{t('bottomNav.settings')}</span>
            </NavLink>
        </nav>
    );
};

export default BottomNavigation;
