import React, { useState, useEffect, useRef } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useContainer } from '../contexts/ContainerContext';
import { useToast } from '../contexts/ToastContext';
import { SharingService } from '../services/sharingService';
import { NotificationService } from '../services/notificationService';
import { UserService } from '../services/userService';
import type { Link as LinkType } from '../types';
import blinkLogo from '../assets/blinklogo2.png';
import { ContainerService } from '../services/containerService';
import {
  ArrowLeft,
  Plus,
  Edit,
  Trash2,
  Share2,
  Settings,
  LogOut,
  Search,
  CheckSquare,
  XCircle,
  ArrowRightLeft,
  X,
  ChevronRight,
  ChevronDown,
  Flag,
  Webhook,
  FileText,
  Link as LinkIcon,
  Folder
} from 'lucide-react';
import AddLinkModal from '../components/AddLinkModal';
import CreateContainerModal from '../components/CreateContainerModal';
import AddTextModal from '../components/AddTextModal';
import ViewTextModal from '../components/ViewTextModal';
import EditLinkModal from '../components/EditLinkModal';
import EditContainerModal from '../components/EditContainerModal';
import WebhooksModal from '../components/WebhooksModal';
import ConfirmModal from '../components/ConfirmModal';
import CollaboratorsModal from '../components/CollaboratorsModal';
import ShareLinkModal from '../components/ShareLinkModal';
import LoadingSkeleton from '../components/LoadingSkeleton';
import SortableLinkItem from '../components/SortableLinkItem';
import MoveLinkModal from '../components/MoveLinkModal';
import LinkStatsModal from '../components/LinkStatsModal';
import QRCodeModal from '../components/QRCodeModal';
import SEO from '../components/SEO';
import EmptyState from '../components/EmptyState';
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  TouchSensor,
  type DragEndEvent
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy
} from '@dnd-kit/sortable';

import { useTranslation } from 'react-i18next';
import SupportButton from '../components/SupportButton';

const ContainerDetails: React.FC = () => {
  const { t } = useTranslation();

  const { id } = useParams<{ id: string }>();
  const { currentUser } = useAuth();
  const {
    containers,
    loading,
    error,
    deleteLinkFromContainer,
    deleteLinksFromContainer,
    deleteContainer,
    reorderLinks,
    updateLinkInContainer,
    trackClick,
    refreshContainers
  } = useContainer();
  const navigate = useNavigate();
  const toast = useToast();
  const [showAddLinkModal, setShowAddLinkModal] = useState(false);
  const [showAddSubcontainerModal, setShowAddSubcontainerModal] = useState(false);
  const [showEditLinkModal, setShowEditLinkModal] = useState(false);

  // Expose setShowAddLinkModal to window for mobile navigation
  useEffect(() => {
    (window as any).dispatchSetShowAddLinkModal = setShowAddLinkModal;
    return () => {
      delete (window as any).dispatchSetShowAddLinkModal;
    };
  }, []);
  const [showEditContainerModal, setShowEditContainerModal] = useState(false);
  const [showWebhooksModal, setShowWebhooksModal] = useState(false);
  const [showDeleteLinkModal, setShowDeleteLinkModal] = useState(false);
  const [showDeleteContainerModal, setShowDeleteContainerModal] = useState(false);
  const [showLeaveContainerModal, setShowLeaveContainerModal] = useState(false);
  const [showCollaboratorsModal, setShowCollaboratorsModal] = useState(false);
  const [showShareLinkModal, setShowShareLinkModal] = useState(false);
  const [showDeleteConfirmModal, setShowDeleteConfirmModal] = useState(false);
  const [showMoveLinkModal, setShowMoveLinkModal] = useState(false);
  const [showBulkMoveModal, setShowBulkMoveModal] = useState(false);
  const [showStatsModal, setShowStatsModal] = useState(false);
  const [showQRCodeModal, setShowQRCodeModal] = useState(false);
  const [selectedLink, setSelectedLink] = useState<LinkType | null>(null);
  const [showAddTextModal, setShowAddTextModal] = useState(false);
  const [showViewTextModal, setShowViewTextModal] = useState(false);
  const [showAddDropdown, setShowAddDropdown] = useState(false);
  const addDropdownRef = useRef<HTMLDivElement>(null);
  const [copiedLinkId, setCopiedLinkId] = useState<string | null>(null);
  const [linkSearchQuery, setLinkSearchQuery] = useState('');
  const [userPermission, setUserPermission] = useState<'view' | 'comment' | 'edit' | null>(null);
  const [collaboratorData, setCollaboratorData] = useState<Record<string, { name: string, username?: string, photoURL?: string }>>({});
  const [showNavbar, setShowNavbar] = useState(true);
  const [lastScrollY, setLastScrollY] = useState(0);
  const [showGuestJoinBanner, setShowGuestJoinBanner] = useState(true);

  // Bulk Selection State
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedLinkIds, setSelectedLinkIds] = useState<Set<string>>(new Set());

  const toggleSelectionMode = () => {
    setSelectionMode(!selectionMode);
    setSelectedLinkIds(new Set());
  };

  const handleSelectLink = (link: LinkType) => {
    const newSelected = new Set(selectedLinkIds);
    if (newSelected.has(link.id)) {
      newSelected.delete(link.id);
    } else {
      newSelected.add(link.id);
    }
    setSelectedLinkIds(newSelected);
  };

  const handleSelectAll = () => {
    if (selectedLinkIds.size === filteredLinks.length) {
      setSelectedLinkIds(new Set());
    } else {
      setSelectedLinkIds(new Set(filteredLinks.map((l: LinkType) => l.id)));
    }
  };

  const handleBulkDelete = () => {
    if (selectedLinkIds.size === 0) return;
    setShowDeleteConfirmModal(true);
  };

  const [deletingLinkId, setDeletingLinkId] = useState<string | null>(null);
  const [deletingLinkIds, setDeletingLinkIds] = useState<Set<string>>(new Set());
  const [publicContainer, setPublicContainer] = useState<any>(null);
  const [fetchingPublic, setFetchingPublic] = useState(false);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (addDropdownRef.current && !addDropdownRef.current.contains(event.target as Node)) {
        setShowAddDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);
  const hasAttemptedFetch = useRef<string | null>(null);

  // Container Report states
  const [showContainerReportModal, setShowContainerReportModal] = useState(false);
  const [containerReportReason, setContainerReportReason] = useState<string>('');
  const [containerOtherReasonText, setContainerOtherReasonText] = useState<string>('');
  const [containerCaptchaToken, setContainerCaptchaToken] = useState<string | null>(null);
  const [containerReportLoading, setContainerReportLoading] = useState(false);
  const containerCaptchaRef = useRef<HTMLDivElement>(null);
  const containerCaptchaWidgetId = useRef<number | null>(null);

  // Find the current container from the containers array or fetch it if public
  const container = (containers.find(v => v.id === id) || publicContainer) || null;
  const childContainers = container ? containers.filter(child => child.parentId === container.id) : [];

  const [newlyAddedLinkId, setNewlyAddedLinkId] = useState<string | null>(null);
  const [prevLinksCount, setPrevLinksCount] = useState(0);

  useEffect(() => {
    if (container && container.links.length > prevLinksCount) {
      // Find the link with the newest createdAt
      const newestLink = [...container.links].sort((a, b) =>
        (b.createdAt as any)?.seconds - (a.createdAt as any)?.seconds
      )[0];

      if (newestLink) {
        setNewlyAddedLinkId(newestLink.id);
        setTimeout(() => setNewlyAddedLinkId(null), 3000); // Clear after 3 seconds
      }
    }
    setPrevLinksCount(container?.links.length || 0);
  }, [container?.links.length, prevLinksCount]);

  const [softDeletedLinks, setSoftDeletedLinks] = useState<Set<string>>(new Set());
  const deleteTimers = useRef<Record<string, any>>({});
  const searchInputRef = useRef<HTMLInputElement>(null);

  const confirmBulkDelete = async () => {
    try {
      if (!container) return;

      // Close modal immediately so animation is visible
      setShowDeleteConfirmModal(false);

      setDeletingLinkIds(new Set(selectedLinkIds));

      // Wait for animation (400ms match CSS)
      await new Promise(resolve => setTimeout(resolve, 400));

      await deleteLinksFromContainer(container.id, Array.from(selectedLinkIds));
      toast.success(t('container.messages.deleted', { count: selectedLinkIds.size }));
      setSelectionMode(false);
      setSelectedLinkIds(new Set());
      setDeletingLinkIds(new Set());
    } catch (err: any) {
      console.error('Bulk delete error:', err);
      toast.error(err.message || t('container.messages.deleteError'));
      setDeletingLinkIds(new Set());
      throw err;
    }
  };

  const handleBulkMove = () => {
    if (selectedLinkIds.size === 0) return;
    setShowBulkMoveModal(true);
  };

  // Navbar scroll behavior - hide on scroll down, show on scroll up
  useEffect(() => {
    const handleScroll = () => {
      const currentScrollY = window.scrollY;

      if (currentScrollY < 10) {
        // Always show navbar at top
        setShowNavbar(true);
      } else if (currentScrollY > lastScrollY) {
        // Scrolling down - hide navbar
        setShowNavbar(false);
      } else {
        // Scrolling up - show navbar
        setShowNavbar(true);
      }

      setLastScrollY(currentScrollY);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [lastScrollY]);

  // Fetch public container if not found in user's containers
  useEffect(() => {
    // Reset if ID changes
    if (id && hasAttemptedFetch.current !== id) {
      hasAttemptedFetch.current = null;
      setPublicContainer(null);
      setFetchingPublic(true);
    }

    const fetchPublicContainer = async () => {
      if (!id) return;

      // Check if we already have it in user's containers
      const foundInContainers = containers.find(v => v.id === id);
      if (foundInContainers) {
        setFetchingPublic(false);
        return;
      }

      // If we already attempted for this ID, don't do it again
      if (hasAttemptedFetch.current === id) {
        // But if we're here and not found in containers, it means it's not our container
        // and fetch already ran once.
        return;
      }

      try {
        setFetchingPublic(true);
        hasAttemptedFetch.current = id;
        const data = await ContainerService.getContainer(id);

        // Only set as public container if it exists and is marked public
        if (data && data.isPublic) {
          setPublicContainer(data);
        } else if (data && !data.isPublic) {
          // It's a private container and we don't have access
          setPublicContainer(null);
        }
      } catch (err) {
        console.error('Error fetching public container:', err);
        setPublicContainer(null);
      } finally {
        setFetchingPublic(false);
      }
    };

    fetchPublicContainer();
  }, [id, containers]);

  // Debug container data
  useEffect(() => {
    if (container) {
      console.log('Current container data:', {
        id: container.id,
        name: container.name,
        ownerId: container.ownerId,
        authorizedUsers: container.authorizedUsers,
        currentUserId: currentUser?.uid
      });
    }
  }, [container, currentUser]);

  // Load collaborator names (including owner if not current user)
  useEffect(() => {
    const loadCollaboratorNames = async () => {
      if (!container) {
        console.log('No container to load');
        return;
      }

      console.log('Loading collaborator names...');
      console.log('Container owner:', container.ownerId);
      console.log('Authorized users:', container.authorizedUsers);
      console.log('Current user:', currentUser?.uid);

      const data: Record<string, { name: string, username?: string, photoURL?: string }> = {};
      const userIdsToFetch = new Set<string>();

      // Add owner if not current user
      if (container.ownerId && container.ownerId !== currentUser?.uid) {
        userIdsToFetch.add(container.ownerId);
      }

      // Add all authorized users who are not current user
      if (container.authorizedUsers && container.authorizedUsers.length > 0) {
        container.authorizedUsers.forEach((userId: string) => {
          if (userId !== currentUser?.uid) {
            userIdsToFetch.add(userId);
          }
        });
      }

      console.log('Fetching names for users:', Array.from(userIdsToFetch));

      // Fetch names for all users
      await Promise.all(
        Array.from(userIdsToFetch).map(async (userId) => {
          try {
            console.log(`Fetching name for user: ${userId}`);
            const userData = await UserService.getUserData(userId);
            console.log(`Got data for ${userId}:`, userData);
            data[userId] = {
              name: userData?.displayName || userData?.email || 'User',
              username: userData?.username,
              photoURL: userData?.photoURL
            };
          } catch (err) {
            console.error(`Failed to fetch name for user ${userId}:`, err);
            data[userId] = { name: 'User' };
          }
        })
      );

      console.log('All collaborator data loaded:', data);
      setCollaboratorData(data);
    };

    loadCollaboratorNames();
  }, [container?.ownerId, container?.authorizedUsers, currentUser?.uid]);

  // Load user permission for this container
  useEffect(() => {
    const loadUserPermission = async () => {
      if (!container || !currentUser) return;

      // Owner has full permissions
      if (container.ownerId === currentUser.uid) {
        setUserPermission('edit');
        return;
      }

      // Check permission for shared users
      const permission = await SharingService.getUserPermission(container.id, currentUser.uid);
      setUserPermission(permission?.permission || (container.isPublic ? 'view' : null));
    };

    loadUserPermission();
  }, [container?.id, container?.isPublic, currentUser]);

  // Set default permission for guests or non-members if public
  useEffect(() => {
    if (container?.isPublic) {
      if (!currentUser) {
        setUserPermission('view');
      } else if (container.ownerId !== currentUser.uid && !container.authorizedUsers.includes(currentUser.uid)) {
        // If logged in but not member, check if we already have permission from sharingService
        if (!userPermission) {
          setUserPermission('view');
        }
      }
    }
  }, [container?.isPublic, container?.ownerId, container?.authorizedUsers, currentUser, userPermission]);

  // Handle Drag and Drop Sensors
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    }),
    useSensor(TouchSensor, {
      activationConstraint: {
        delay: 250,
        tolerance: 5,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;

    if (over && active.id !== over.id && container) {
      const oldIndex = container.links.findIndex((l: LinkType) => l.id === active.id);
      const newIndex = container.links.findIndex((l: LinkType) => l.id === over.id);

      const newLinks = arrayMove(container.links, oldIndex, newIndex);

      try {
        await (reorderLinks as any)(container.id, newLinks);
        toast.success(t('container.messages.orderUpdated'));
      } catch (err: any) {
        toast.error(t('container.messages.updateOrderError'));
      }
    }
  };

  const handleMoveLink = (link: LinkType) => {
    setSelectedLink(link);
    setShowMoveLinkModal(true);
  };

  // Filter links based on search query
  const filteredLinks = container?.links.filter((link: LinkType) => {
    if (softDeletedLinks.has(link.id)) return false;
    const query = linkSearchQuery.toLowerCase();
    return (
      link.title.toLowerCase().includes(query) ||
      link.description?.toLowerCase().includes(query) ||
      link.url.toLowerCase().includes(query)
    );
  }) || [];

  // Sort: Pinned links stay at the top
  const sortedLinks = [...filteredLinks].sort((a, b) => {
    if (a.isPinned && !b.isPinned) return -1;
    if (!a.isPinned && b.isPinned) return 1;
    return 0; // Maintain original order otherwise
  });

  const copyToClipboard = (url: string, linkId: string) => {
    navigator.clipboard.writeText(url);
    setCopiedLinkId(linkId);
    setTimeout(() => setCopiedLinkId(null), 2000);
  };

  const handleEditLink = (link: LinkType) => {
    setSelectedLink(link);
    if (link.type === 'text') {
      setShowAddTextModal(true);
    } else {
      setShowEditLinkModal(true);
    }
  };

  const handleDeleteLink = (link: LinkType) => {
    if (!container) return;

    // 1. Mark as disintegrating to trigger CSS animation
    setDeletingLinkId(link.id);

    // 2. Wait for animation, then soft delete and show Toast with Undo
    setTimeout(() => {
      setDeletingLinkId(null);
      setSoftDeletedLinks(prev => new Set(prev).add(link.id));

      const timerId = setTimeout(async () => {
        try {
          await deleteLinkFromContainer(container.id, link.id);
        } catch (err: any) {
          console.error('Error hard deleting link:', err);
        }
        delete deleteTimers.current[link.id];
      }, 5000);

      deleteTimers.current[link.id] = timerId;

      toast.success(t('container.messages.linkDeleted'), 5000, {
        label: t('common.undo') || 'Undo',
        onClick: () => {
          clearTimeout(deleteTimers.current[link.id]);
          delete deleteTimers.current[link.id];
          setSoftDeletedLinks(prev => {
            const next = new Set(prev);
            next.delete(link.id);
            return next;
          });
        }
      });
    }, 400); // 400ms match current CSS fadeOut
  };

  const handleTogglePin = async (link: LinkType) => {
    if (!container) return;
    try {
      await updateLinkInContainer(container.id, link.id, { isPinned: !link.isPinned });
      toast.success(link.isPinned ? t('container.messages.unpinned') : t('container.messages.pinned'));
    } catch (err: any) {
      toast.error(t('container.messages.pinError'));
    }
  };

  const handleUpdateLink = async (linkId: string, updates: Partial<LinkType>) => {
    if (!container) return;
    try {
      await updateLinkInContainer(container.id, linkId, updates);
    } catch (err: any) {
      toast.error('Failed to update link');
    }
  };

  const handleTrackClick = (linkId: string) => {
    if (!container) return;
    trackClick(container.id, linkId);
  };

  const handleShowStats = (link: LinkType) => {
    setSelectedLink(link);
    setShowStatsModal(true);
  };

  const handleShowQRCode = (link: LinkType) => {
    setSelectedLink(link);
    setShowQRCodeModal(true);
  };

  const confirmDeleteLink = async () => { };

  const [isDeletingContainer, setIsDeletingContainer] = useState(false);

  const confirmDeleteContainer = async () => {
    if (!container) return;
    try {
      // Close modal immediately
      setShowDeleteContainerModal(false);

      setIsDeletingContainer(true);

      // Wait for animation
      await new Promise(resolve => setTimeout(resolve, 400));

      await deleteContainer(container.id);
      toast.success(t('container.messages.containerDeleted'));
      navigate('/dashboard');
    } catch (err: any) {
      console.error('Error deleting container:', err);
      toast.error(err.message || t('container.messages.containerDeleteError'));
      setIsDeletingContainer(false);
    }
  };

  const confirmLeaveContainer = async () => {
    if (!container || !currentUser) return;
    try {
      await SharingService.removeUserFromContainer(container.id, currentUser.uid);
      setShowLeaveContainerModal(false);

      // Notify the container owner
      try {
        const leaverName = UserService.formatUserName(currentUser.displayName, currentUser.email);
        await NotificationService.notifyContainerLeft(
          container.ownerId,
          container.name,
          leaverName,
          container.id,
          currentUser.uid
        );
      } catch (notifErr) {
        console.error('Failed to send leave notification:', notifErr);
      }

      // Refresh containers so collaborators list updates in real-time
      await refreshContainers();

      toast.success(t('container.messages.leftContainer'));
      navigate('/dashboard');
    } catch (err: any) {
      console.error('Error leaving container:', err);
      toast.error(err.message || t('container.messages.leaveError'));
      setShowLeaveContainerModal(false);
    }
  };

  // Check if current user is the owner
  const isOwner = !!container && !!currentUser && container.ownerId === currentUser.uid;

  // Check if user can edit (owner or has edit permission)
  const canEdit = isOwner || userPermission === 'edit';

  // Check if current user is a member (owner or explicitly authorized)
  const isMember = isOwner || !!(container && currentUser && container.authorizedUsers?.includes(currentUser.uid));

  // --- Report Container Functions ---
  const CONTAINER_REPORT_REASONS = [
    { key: 'spam', labelKey: 'container.report.reasonSpam' },
    { key: 'harassment', labelKey: 'container.report.reasonHarassment' },
    { key: 'fake', labelKey: 'container.report.reasonFake' },
    { key: 'hate', labelKey: 'container.report.reasonHate' },
    { key: 'inappropriate', labelKey: 'container.report.reasonInappropriate' },
    { key: 'other', labelKey: 'container.report.reasonOther' },
  ];

  const handleReportContainer = () => {
    if (!container) return;
    const reportKey = `reported_container_${container.id}`;
    if (localStorage.getItem(reportKey)) {
      toast.error(t('container.report.alreadyReported'));
      return;
    }
    setContainerReportReason('');
    setContainerOtherReasonText('');
    setContainerCaptchaToken(null);
    setShowContainerReportModal(true);
  };

  useEffect(() => {
    if (!showContainerReportModal) {
      containerCaptchaWidgetId.current = null;
      return;
    }
    const tryRender = () => {
      if (containerCaptchaRef.current && (window as any).grecaptcha && containerCaptchaWidgetId.current === null) {
        containerCaptchaRef.current.innerHTML = '';
        const rawSiteKey = import.meta.env.VITE_RECAPTCHA_SITE_KEY;
        const siteKey = (typeof rawSiteKey === 'string' && rawSiteKey.trim() !== '' && rawSiteKey !== 'undefined' && rawSiteKey !== 'null')
          ? rawSiteKey.trim()
          : '6LesqY4sAAAAAOrGlOMHkPPc4XRYbcH0XODv2C-w';
        containerCaptchaWidgetId.current = (window as any).grecaptcha.render(containerCaptchaRef.current, {
          sitekey: siteKey,
          callback: (token: string) => setContainerCaptchaToken(token),
          'expired-callback': () => setContainerCaptchaToken(null),
        });
      } else {
        setTimeout(tryRender, 300);
      }
    };
    setTimeout(tryRender, 150);
  }, [showContainerReportModal]);

  const submitContainerReport = async () => {
    if (!container) return;
    if (!containerReportReason) {
      toast.error(t('container.report.selectReason'));
      return;
    }
    if (containerReportReason === 'other' && !containerOtherReasonText.trim()) {
      toast.error(t('container.report.provideDetails'));
      return;
    }
    if (!containerCaptchaToken) {
      toast.error(t('container.report.completeCaptcha'));
      return;
    }
    setContainerReportLoading(true);
    try {
      const now = new Date().toISOString();
      const body = new FormData();
      body.append('_subject', 'Report Container');
      body.append('reason', containerReportReason === 'other' ? `Other: ${containerOtherReasonText}` : containerReportReason);
      body.append('reported_container_id', container.id);
      body.append('reported_container_name', container.name || '');
      body.append('reported_container_owner', container.ownerId || '');
      body.append('reported_at', now);
      body.append('g-recaptcha-response', containerCaptchaToken);
      if (currentUser) {
        body.append('reporter_uid', currentUser.uid);
        body.append('reporter_email', currentUser.email || '');
      }
      const formUrl = import.meta.env.VITE_FORMSPREE_REPORT_CONTAINER_URL || 'https://formspree.io/f/mqeywpqv';
      const res = await fetch(formUrl, {
        method: 'POST',
        body,
        headers: { Accept: 'application/json' },
      });
      if (res.ok) {
        const reportKey = `reported_container_${container.id}`;
        localStorage.setItem(reportKey, now);
        setShowContainerReportModal(false);
        toast.success(t('container.report.sent'));
      } else {
        toast.error(t('container.report.failed'));
      }
    } catch {
      toast.error(t('container.report.failed'));
    } finally {
      setContainerReportLoading(false);
    }
  };
  // ----------------------------------

  const colors = ['#6366f1', '#10b981', '#f43f5e', '#d97706', '#8b5cf6', '#3b82f6', '#0891b2', '#ea580c', '#6d28d9', '#be185d'];
  const containerColor = container?.color || colors[(container?.id || '').split('').reduce((acc: number, char: string) => acc + char.charCodeAt(0), 0) % colors.length] || '#6366f1';

  // Helper to get RGB from hex
  const hexToRgb = (hex: string) => {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result ?
      `${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}` :
      '99, 102, 241';
  };

  // These hooks MUST be before any conditional returns to comply with Rules of Hooks
  const isLightColor = React.useMemo(() => {
    const rgb = hexToRgb(containerColor).split(',').map(Number);
    if (rgb.length === 3) {
      const luminance = (0.299 * rgb[0] + 0.587 * rgb[1] + 0.114 * rgb[2]) / 255;
      return luminance > 0.65;
    }
    return false;
  }, [containerColor]);

  React.useEffect(() => {
    if (isLightColor) {
      document.body.classList.add('light-container-theme');
    } else {
      document.body.classList.remove('light-container-theme');
    }
    return () => {
      document.body.classList.remove('light-container-theme');
    };
  }, [isLightColor]);

  if (loading || fetchingPublic) {
    return <LoadingSkeleton variant="fullscreen" />;
  }

  if (!container) {
    return (
      <div className="min-h-screen bg-background-light dark:bg-background-dark flex items-center justify-center">
        <div className="text-center">
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white mb-4">{t('container.notFound.title')}</h1>
          <Link to="/dashboard" className="text-primary hover:text-primary/80">
            {t('container.notFound.return')}
          </Link>
        </div>
      </div>
    );
  }



  return (
    <div
      className={`container-details-page fixed-layout-page ${isLightColor ? 'light-container-theme' : ''}`}
      style={{
        '--accent-color': containerColor,
        '--primary': containerColor,
        '--primary-rgb': hexToRgb(containerColor)
      } as React.CSSProperties}
    >
      <SEO
        title={container.name}
        description={container.description || t('container.description', { name: container.name })}
      />
      <header className={`header ${showNavbar ? 'navbar-visible' : 'navbar-hidden'}`}>
        <div className="container">
          <div className="header-content">
            <div className="header-left">
              <Link to="/dashboard" className="back-link">
                <ArrowLeft />
              </Link>
              <img src={blinkLogo} alt="Blink" className="logo-image" style={{ height: '40px', width: 'auto', marginLeft: '1rem' }} />
            </div>
            <div className="header-right">
              <Link to="/settings" className="settings-link" title={t('dashboard.tooltips.settings')}>
                <Settings size={20} />
              </Link>
              <div className="hidden md:flex">
                <SupportButton />
              </div>
              {currentUser ? (
                <Link to={currentUser.username ? `/u/${currentUser.username}` : '#'} className="user-avatar-link">
                  <div
                    className="user-avatar"
                    style={{
                      backgroundImage: currentUser.photoURL ? `url(${currentUser.photoURL})` : undefined,
                      backgroundSize: 'cover',
                      backgroundPosition: 'center',
                      overflow: 'hidden'
                    }}
                  >
                    {!currentUser.photoURL && (currentUser.displayName?.charAt(0).toUpperCase() || 'U')}
                  </div>
                </Link>
              ) : (
                <div className="user-avatar">G</div>
              )}
            </div>
          </div>
        </div>
      </header>

      <main className={`container fade-in ${isDeletingContainer ? 'disintegrate' : ''}`}>
        {/* Guest Join Banner */}
        {!currentUser && container.isPublic && showGuestJoinBanner && (
          <div className="guest-join-footer">
            <button
              className="guest-join-close"
              onClick={() => setShowGuestJoinBanner(false)}
              aria-label="Close"
            >
              <X size={18} />
            </button>
            <div className="guest-join-info">
              <h4>{t('container.guest.joinTitle')}</h4>
              <p>{t('container.guest.joinDesc')}</p>
            </div>
            <Link to="/signup" className="guest-signup-btn">
              {t('container.guest.signup')}
            </Link>
          </div>
        )}
        <div className="container-content">
          <div className="links-section">
            <div className="container-header" style={{ marginBottom: '1.5rem' }}>
              <div className="container-header-info">
                {container.parentId && (
                  <Link to={`/c/${container.parentId}`} className="container-breadcrumb">
                    <ArrowLeft size={14} />
                    {containers.find(parent => parent.id === container.parentId)?.name || t('container.parent')}
                  </Link>
                )}
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '1rem' }}>
                  <h2 className="container-name-title" style={{ margin: 0 }}>{container.name}</h2>
                  {!isOwner && (
                    <button
                      onClick={handleReportContainer}
                      className="profile-icon-btn profile-report-btn"
                      title={t('container.report.title')}
                      style={{ width: '36px', height: '36px', flexShrink: 0 }}
                    >
                      <Flag size={18} />
                    </button>
                  )}
                </div>
                {container.description && <p className="container-description-text" style={{ marginTop: '0.5rem' }}>{container.description}</p>}
              </div>
            </div>
            <div className="links-header" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1rem' }}>
              <h3>{t('container.links')} ({container.links.length})</h3>
              <div style={{ display: 'flex', gap: '8px' }}>
                <button
                  onClick={toggleSelectionMode}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '6px',
                    padding: '8px 12px',
                    fontSize: '0.875rem',
                    fontWeight: '500',
                    borderRadius: '8px',
                    border: selectionMode ? '1px solid var(--primary)' : '1px solid var(--border-color)',
                    backgroundColor: selectionMode ? 'rgba(var(--primary-rgb), 0.1)' : 'transparent',
                    color: selectionMode ? 'var(--primary)' : 'var(--text-secondary)',
                    cursor: 'pointer',
                    transition: 'all 0.2s ease',
                    outline: 'none'
                  }}
                  title={selectionMode ? 'Cancel Selection' : 'Select Multiple'}
                >
                  {selectionMode ? <XCircle size={16} /> : <CheckSquare size={16} />}
                  <span className="hidden sm:inline">{selectionMode ? t('container.cancel') : t('container.select')}</span>
                </button>
                {canEdit && (
                  <div className="add-content-dropdown-wrapper" ref={addDropdownRef}>
                    <div className="split-button-container">
                      <button
                        onClick={() => setShowAddLinkModal(true)}
                        className="main-add-button"
                        title={t('container.addLink')}
                      >
                        <Plus size={18} />
                        <span>{t('container.addLink')}</span>
                      </button>
                      <button
                        onClick={() => setShowAddDropdown(!showAddDropdown)}
                        className={`dropdown-toggle-button ${showAddDropdown ? 'active' : ''}`}
                        title={t('container.addContent')}
                      >
                        <ChevronDown size={16} />
                      </button>
                    </div>
                    {showAddDropdown && (
                      <div className="add-content-menu glass-card fade-in">
                        <button
                          className="add-content-item"
                          onClick={() => {
                            setShowAddSubcontainerModal(true);
                            setShowAddDropdown(false);
                          }}
                        >
                          <Folder size={16} />
                          <span>{t('container.subcontainers.add')}</span>
                        </button>
                        <button
                          className="add-content-item"
                          onClick={() => {
                            setShowAddLinkModal(true);
                            setShowAddDropdown(false);
                          }}
                        >
                          <LinkIcon size={16} />
                          <span>{t('container.typeLink')}</span>
                        </button>
                        <button
                          className="add-content-item"
                          onClick={() => {
                            setShowAddTextModal(true);
                            setShowAddDropdown(false);
                          }}
                        >
                          <FileText size={16} />
                          <span>{t('container.typeText')}</span>
                        </button>
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>

            {/* Search Input */}
            {container.links.length > 0 && !selectionMode && (
              <div className="modern-search-bar search-links-wrapper">
                <Search className="modern-search-icon" size={18} />
                <input
                  ref={searchInputRef}
                  type="text"
                  placeholder={t('container.searchLinks')}
                  value={linkSearchQuery}
                  onChange={(e) => setLinkSearchQuery(e.target.value)}
                  className="modern-search-input"
                />
              </div>
            )}

            {/* Bulk Selection Header */}
            {selectionMode && (
              <div className="card mb-4 flex items-center justify-between" style={{ padding: '1rem' }}>
                <div className="flex items-center gap-3">
                  <input
                    type="checkbox"
                    checked={filteredLinks.length > 0 && selectedLinkIds.size === filteredLinks.length}
                    onChange={handleSelectAll}
                    className="w-5 h-5 cursor-pointer"
                    style={{ accentColor: 'var(--primary)' }}
                  />
                  <span className="font-medium">{selectedLinkIds.size} {t('container.selected')}</span>
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={handleBulkMove}
                    disabled={selectedLinkIds.size === 0}
                    className="btn-secondary rounded-lg disabled:opacity-50"
                    title="Move Selected"
                    style={{
                      padding: '6px 10px',
                      height: '36px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      backgroundColor: 'var(--bg-secondary)',
                      color: 'var(--text-primary)',
                      border: '1px solid var(--border-color)'
                    }}
                  >
                    <ArrowRightLeft size={18} />
                  </button>
                  <button
                    onClick={handleBulkDelete}
                    disabled={selectedLinkIds.size === 0}
                    className="btn-danger rounded-lg disabled:opacity-50"
                    title="Delete Selected"
                    style={{ padding: '6px 10px', height: '36px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>
            )}

            {childContainers.length > 0 && (
              <div className="asset-folders-list">
                {childContainers.map(child => (
                  <Link
                    key={child.id}
                    to={`/c/${child.id}`}
                    className="asset-folder-card"
                    style={{ '--folder-color': child.color || containerColor } as React.CSSProperties}
                  >
                    <span className="asset-folder-icon"><Folder size={20} /></span>
                    <span className="asset-folder-copy">
                      <strong>{child.name}</strong>
                      <small>
                        {child.description || t('container.subcontainers.emptyDescription')}
                        {' · '}
                        {t('container.assetCount', { count: child.links.length })}
                      </small>
                    </span>
                    <ChevronRight size={19} className="asset-folder-arrow" />
                  </Link>
                ))}
              </div>
            )}

            <div className="links-list">
              {container.links.length === 0 ? (
                <div className="fade-in">
                  <EmptyState
                    type="links"
                    title={t('container.empty')}
                    description={t('container.emptyDesc')}
                  />
                </div>
              ) : filteredLinks.length === 0 ? (
                <div className="fade-in">
                  <EmptyState
                    type="search"
                    title={t('container.emptySearch')}
                    description={t('container.emptySearchDesc')}
                  />
                </div>
              ) : (
                <DndContext
                  sensors={sensors}
                  collisionDetection={closestCenter}
                  onDragEnd={handleDragEnd}
                >
                  <SortableContext
                    items={sortedLinks.map(l => l.id)}
                    strategy={verticalListSortingStrategy}
                  >
                    <div className="links-cards-grid">
                      {sortedLinks.map((link) => (
                        <SortableLinkItem
                          key={link.id}
                          link={link}
                          canEdit={canEdit}
                          disabled={linkSearchQuery.trim().length > 0 || link.isPinned || selectionMode} // Disable drag if searching OR if pinned OR selecting
                          copiedLinkId={copiedLinkId}
                          onCopy={copyToClipboard}
                          onEdit={handleEditLink}
                          onDelete={handleDeleteLink}
                          onMove={handleMoveLink}
                          onTogglePin={handleTogglePin}
                          onStats={handleShowStats}
                          onQRCode={handleShowQRCode}
                          onTrackClick={handleTrackClick}
                          selectionMode={selectionMode}
                          isSelected={selectedLinkIds.has(link.id)}
                          onSelect={handleSelectLink}
                          isDeleting={deletingLinkId === link.id || deletingLinkIds.has(link.id)}
                          isNewlyAdded={newlyAddedLinkId === link.id}
                          onUpdateLink={handleUpdateLink}
                          currentUserId={currentUser?.uid}
                          onViewText={(link) => {
                            setSelectedLink(link);
                            setShowViewTextModal(true);
                            handleTrackClick(link.id);
                          }}
                        />
                      ))}
                    </div>
                  </SortableContext>
                </DndContext>
              )}
            </div>
          </div>

          <aside className="sidebar">
            <div className="collaborators-widget">
              <h3>{t('container.collaborators.title')}</h3>
              <div
                className="collaborators-clickable-area"
                onClick={() => setShowCollaboratorsModal(true)}
              >
                <div className="collaborators-list">
                  {/* Current User - Only show if member */}
                  {currentUser && isMember && (
                    <Link
                      to={currentUser.username ? `/u/${currentUser.username}` : '#'}
                      className="avatar overflow-hidden hover:opacity-80 transition-opacity"
                      title={currentUser.displayName || t('container.collaborators.you')}
                    >
                      {currentUser.photoURL ? (
                        <img src={currentUser.photoURL} alt="" className="w-full h-full object-cover" />
                      ) : (
                        currentUser.displayName?.charAt(0).toUpperCase() || 'U'
                      )}
                    </Link>
                  )}

                  {/* Owner (if not current user) */}
                  {container.ownerId !== currentUser?.uid && (
                    collaboratorData[container.ownerId]?.username ? (
                      <Link
                        to={`/u/${collaboratorData[container.ownerId].username}`}
                        key={container.ownerId}
                        className="avatar overflow-hidden hover:opacity-80 transition-opacity"
                        title={`${collaboratorData[container.ownerId]?.name || 'Owner'} (${t('container.collaborators.owner')})`}
                      >
                        {collaboratorData[container.ownerId]?.photoURL ? (
                          <img src={collaboratorData[container.ownerId].photoURL} alt="" className="w-full h-full object-cover" />
                        ) : (
                          (collaboratorData[container.ownerId]?.name || 'O').charAt(0).toUpperCase()
                        )}
                      </Link>
                    ) : (
                      <div
                        key={container.ownerId}
                        className="avatar"
                        title={`${collaboratorData[container.ownerId]?.name || 'Owner'} (${t('container.collaborators.owner')})`}
                      >
                        {(collaboratorData[container.ownerId]?.name || 'O').charAt(0).toUpperCase()}
                      </div>
                    )
                  )}

                  {/* Other Authorized Users (excluding owner and current user) */}
                  {(container.authorizedUsers || [])
                    .filter((userId: string) => userId !== currentUser?.uid && userId !== container.ownerId)
                    .slice(0, 2)
                    .map((userId: string) => {
                      const userData = collaboratorData[userId];
                      const userName = userData?.name || 'Loading...';

                      if (userData?.username) {
                        return (
                          <Link
                            key={userId}
                            to={`/u/${userData.username}`}
                            className="avatar overflow-hidden hover:opacity-80 transition-opacity"
                            title={userName}
                          >
                            {userData.photoURL ? (
                              <img src={userData.photoURL} alt="" className="w-full h-full object-cover" />
                            ) : (
                              userName.charAt(0).toUpperCase()
                            )}
                          </Link>
                        );
                      }

                      return (
                        <div key={userId} className="avatar" title={userName}>
                          {userName.charAt(0).toUpperCase()}
                        </div>
                      );
                    })}

                  {/* Show +N more if there are additional collaborators */}
                  {(() => {
                    const otherUsers = (container.authorizedUsers || []).filter(
                      (userId: string) => userId !== currentUser?.uid && userId !== container.ownerId
                    );
                    const remainingCount = otherUsers.length - 2;
                    return remainingCount > 0 && (
                      <div className="avatar" title={t('container.collaborators.more', { count: remainingCount })}>
                        +{remainingCount}
                      </div>
                    );
                  })()}
                </div>
                <ChevronRight size={20} className="collaborators-chevron" />
              </div>
            </div>

            {isMember && (
              <div className="actions-widget">
                <h3>{t('container.actions.title')}</h3>
                <div className="actions-list">
                  {isOwner && (
                    <button
                      onClick={() => setShowEditContainerModal(true)}
                      className="action-button"
                    >
                      <div className="action-icon-wrapper edit-icon">
                        <Edit size={18} />
                      </div>
                      <span>{t('container.actions.editContainer')}</span>
                      <ChevronRight size={18} className="action-button-arrow" />
                    </button>
                  )}
                  {canEdit && (
                    <Link
                      to={`/c/${container.id}/share`}
                      className="action-button"
                    >
                      <div className="action-icon-wrapper share-icon">
                        <Share2 size={18} />
                      </div>
                      <span>{t('container.actions.shareContainer')}</span>
                      <ChevronRight size={18} className="action-button-arrow" />
                    </Link>
                  )}
                  {isOwner && (
                    <button onClick={() => setShowWebhooksModal(true)} className="action-button">
                      <div className="action-icon-wrapper edit-icon">
                        <Webhook size={18} />
                      </div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flex: 1 }}>
                        <span>{t('container.actions.webhooks')}</span>
                      </div>
                      <ChevronRight size={18} className="action-button-arrow" />
                    </button>
                  )}
                  {isOwner ? (
                    <button
                      onClick={() => setShowDeleteContainerModal(true)}
                      className="action-button delete-button"
                    >
                      <div className="action-icon-wrapper delete-icon">
                        <Trash2 size={18} />
                      </div>
                      <span>{t('container.actions.deleteContainer')}</span>
                      <ChevronRight size={18} className="action-button-arrow delete-arrow" />
                    </button>
                  ) : isMember ? (
                    <button
                      onClick={() => setShowLeaveContainerModal(true)}
                      className="action-button delete-button"
                    >
                      <div className="action-icon-wrapper delete-icon">
                        <LogOut size={18} />
                      </div>
                      <span>{t('container.actions.leaveContainer')}</span>
                      <ChevronRight size={18} className="action-button-arrow delete-arrow" />
                    </button>
                  ) : null}
                </div>
              </div>
            )}
          </aside>
        </div>

        {
          error && (
            <div className="error-message">
              {error}
            </div>
          )
        }
      </main >

      {/* Add Link Modal */}
      {
        container && canEdit && (
          <AddLinkModal
            isOpen={showAddLinkModal}
            onClose={() => setShowAddLinkModal(false)}
            containerId={container.id}
            containerColor={containerColor}
          />
        )
      }

      {container && canEdit && (
        <CreateContainerModal
          isOpen={showAddSubcontainerModal}
          onClose={() => setShowAddSubcontainerModal(false)}
          parentId={container.id}
          parentName={container.name}
        />
      )}

      {/* Add Text Modal */}
      {
        container && canEdit && (
          <AddTextModal
            isOpen={showAddTextModal}
            onClose={() => {
              setShowAddTextModal(false);
              setSelectedLink(null);
            }}
            containerId={id || ''}
            containerColor={container.color}
            editLink={selectedLink && selectedLink.type === 'text' ? selectedLink : undefined}
          />
        )
      }


      {/* View Text Modal */}
      {
        container && selectedLink && (
          <ViewTextModal
            isOpen={showViewTextModal}
            onClose={() => {
              setShowViewTextModal(false);
              setSelectedLink(null);
            }}
            link={selectedLink}
            containerColor={containerColor}
          />
        )
      }

      {/* Edit Link Modal */}
      {
        container && selectedLink && canEdit && (
          <EditLinkModal
            isOpen={showEditLinkModal}
            onClose={() => {
              setShowEditLinkModal(false);
              setSelectedLink(null);
            }}
            containerId={container.id}
            link={selectedLink}
            containerColor={containerColor}
          />
        )
      }

      {/* Edit Container Modal */}
      {
        container && isOwner && (
          <EditContainerModal
            isOpen={showEditContainerModal}
            onClose={() => setShowEditContainerModal(false)}
            container={container}
          />
        )
      }

      {/* Webhooks Modal */}
      {
        container && isOwner && (
          <WebhooksModal
            isOpen={showWebhooksModal}
            onClose={() => setShowWebhooksModal(false)}
            container={container}
          />
        )
      }

      {/* Delete Link Confirmation */}
      {
        selectedLink && (
          <ConfirmModal
            isOpen={showDeleteLinkModal}
            onClose={() => {
              setShowDeleteLinkModal(false);
              setSelectedLink(null);
            }}
            onConfirm={confirmDeleteLink}
            title={t('container.modals.deleteLink.title')}
            message={t('container.modals.deleteLink.message', { title: selectedLink.title })}
            confirmText={t('container.modals.deleteLink.confirm')}
            variant="danger"
            icon={<Trash2 size={18} />}
          />
        )
      }

      {/* Delete Container Confirmation */}
      {
        container && (
          <ConfirmModal
            isOpen={showDeleteContainerModal}
            onClose={() => setShowDeleteContainerModal(false)}
            onConfirm={confirmDeleteContainer}
            title={t('container.modals.deleteContainer.title')}
            message={t('container.modals.deleteContainer.confirmMessage')}
            confirmText={t('common.buttons.yes')}
            cancelText={t('common.buttons.no')}
            variant="danger"
            icon={<Trash2 size={18} />}
          />
        )
      }

      {/* Leave Container Confirmation */}
      {
        container && (
          <ConfirmModal
            isOpen={showLeaveContainerModal}
            onClose={() => setShowLeaveContainerModal(false)}
            onConfirm={confirmLeaveContainer}
            title="Leave Container"
            message={`Are you sure you want to leave "${container.name}"? You will lose access to all its contents.`}
            confirmText="Leave Container"
            variant="danger"
            confirmWord="LEAVE"
          />
        )
      }

      {/* Collaborators Modal */}
      {
        container && (
          <CollaboratorsModal
            isOpen={showCollaboratorsModal}
            onClose={() => setShowCollaboratorsModal(false)}
            containerId={container.id}
            authorizedUsers={container.authorizedUsers || []}
            ownerId={container.ownerId}
            currentUserId={currentUser?.uid || null}
            containerColor={containerColor}
          />
        )
      }

      {/* Share Link Modal */}
      {
        container && currentUser && (
          <ShareLinkModal
            isOpen={showShareLinkModal}
            onClose={() => setShowShareLinkModal(false)}
            containerId={container.id}
            containerName={container.name}
            currentUserId={currentUser.uid}
            containerColor={containerColor}
          />
        )
      }

      {/* Move Link Modal (Single) */}
      {
        container && selectedLink && (
          <MoveLinkModal
            isOpen={showMoveLinkModal}
            onClose={() => {
              setShowMoveLinkModal(false);
              setSelectedLink(null);
            }}
            link={selectedLink}
            currentContainerId={container.id}
            containerColor={containerColor}
          />
        )
      }

      {/* Move Link Modal (Bulk) */}
      {
        container && showBulkMoveModal && (
          <MoveLinkModal
            isOpen={showBulkMoveModal}
            onClose={() => {
              setShowBulkMoveModal(false);
              setSelectionMode(false);
              setSelectedLinkIds(new Set());
            }}
            linkIds={Array.from(selectedLinkIds)}
            currentContainerId={container.id}
            containerColor={containerColor}
          />
        )
      }

      {/* Bulk Delete Confirm Modal */}
      {
        container && showDeleteConfirmModal && (
          <ConfirmModal
            isOpen={showDeleteConfirmModal}
            onClose={() => setShowDeleteConfirmModal(false)}
            onConfirm={confirmBulkDelete}
            title="Delete Selected Links"
            message={`Are you sure you want to delete these ${selectedLinkIds.size} selected links? This action cannot be undone.`}
            confirmText={`Delete ${selectedLinkIds.size} Links`}
            variant="danger"
            icon={<Trash2 size={18} />}
          />
        )
      }

      {/* Link Stats Modal */}
      {
        container && selectedLink && (
          <LinkStatsModal
            isOpen={showStatsModal}
            onClose={() => {
              setShowStatsModal(false);
              setSelectedLink(null);
            }}
            link={selectedLink}
            containerColor={containerColor}
          />
        )
      }

      {/* QR Code Modal */}
      {
        container && selectedLink && (
          <QRCodeModal
            isOpen={showQRCodeModal}
            onClose={() => {
              setShowQRCodeModal(false);
              setSelectedLink(null);
            }}
            link={selectedLink}
            containerColor={containerColor}
          />
        )
      }

      {/* Container Report Modal */}
      {showContainerReportModal && (
        <div className="follow-modal-overlay" onClick={() => !containerReportLoading && setShowContainerReportModal(false)}>
          <div className="follow-modal-content report-modal" onClick={e => e.stopPropagation()}>
            <div className="follow-modal-header">
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                <Flag size={18} style={{ color: '#ef4444' }} />
                <h3 style={{ color: '#ef4444', margin: 0, fontSize: '1.25rem', fontWeight: 700 }}>{t('container.report.title')}</h3>
              </div>
              <button className="follow-modal-close" onClick={() => setShowContainerReportModal(false)} disabled={containerReportLoading}>
                <X size={20} />
              </button>
            </div>
            <div className="follow-modal-body report-modal-body">
              <p className="report-modal-desc">{t('container.report.desc')}</p>
              <div className="report-reasons-grid">
                {CONTAINER_REPORT_REASONS.map(r => (
                  <button
                    key={r.key}
                    className={`report-reason-chip${containerReportReason === r.key ? ' selected' : ''}`}
                    onClick={() => setContainerReportReason(r.key)}
                  >
                    {t(r.labelKey)}
                  </button>
                ))}
              </div>
              {containerReportReason === 'other' && (
                <textarea
                  className="report-other-textarea"
                  placeholder={t('container.report.otherPlaceholder')}
                  value={containerOtherReasonText}
                  onChange={(e) => setContainerOtherReasonText(e.target.value)}
                  rows={3}
                />
              )}
              <div className="report-captcha-wrap">
                <div ref={containerCaptchaRef} />
              </div>
              <button
                className="report-submit-btn"
                onClick={submitContainerReport}
                disabled={
                  containerReportLoading ||
                  !containerReportReason ||
                  (containerReportReason === 'other' && !containerOtherReasonText.trim()) ||
                  !containerCaptchaToken
                }
              >
                {containerReportLoading ? t('common.processing') : t('container.report.submit')}
              </button>
            </div>
          </div>
        </div>
      )}

    </div >
  );
};

export default ContainerDetails; 
